import { test, expect } from '@playwright/test';

test.describe('Animated Transitions Between Async Page Loads', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard');
  });

  test('should display loading indicator while waiting for async page load', async ({ page }) => {
    // Verify initial state: no loading indicator
    const loadingIndicator = page.getByRole('status');
    await expect(loadingIndicator).not.toBeVisible();

    // Click the button to load new page
    const loadButton = page.getByRole('button', { name: /load new page/i });
    await loadButton.click();

    // Verify loading indicator appears
    await expect(loadingIndicator).toBeVisible();

    // Wait for the async load to complete
    await page.waitForLoadState('networkidle');

    // Verify loading indicator disappears
    await expect(loadingIndicator).not.toBeVisible();

    // Verify new page content is loaded
    const pageTitle = page.getByRole('heading', { name: /dashboard/i });
    await expect(pageTitle).toBeVisible();

    // Verify page content is visible
    const content = page.getByRole('main');
    await expect(content).toBeVisible();
  });

  test('should handle failed async page load with error message and retry button', async ({ page }) => {
    // Click the button to load new page
    const loadButton = page.getByRole('button', { name: /load new page/i });
    await loadButton.click();

    // Verify loading indicator appears
    const loadingIndicator = page.getByRole('status');
    await expect(loadingIndicator).toBeVisible();

    // Simulate failed load
    await page.route('**/api/dashboard', route => {
      route.abort('failed');
    });

    // Wait for error state
    await page.waitForLoadState('networkidle');

    // Verify error message is displayed
    const errorMessage = page.getByText(/error loading page/i);
    await expect(errorMessage).toBeVisible();

    // Verify retry button is available
    const retryButton = page.getByRole('button', { name: /retry/i });
    await expect(retryButton).toBeVisible();

    // Verify loading indicator is still visible
    await expect(loadingIndicator).toBeVisible();

    // Click retry button
    await retryButton.click();

    // Wait for the retry to complete
    await page.waitForLoadState('networkidle');

    // Verify error message is gone
    await expect(errorMessage).not.toBeVisible();

    // Verify loading indicator disappears
    await expect(loadingIndicator).not.toBeVisible();

    // Verify page content is now visible
    const content = page.getByRole('main');
    await expect(content).toBeVisible();
  });
});
